import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十七卦 頤 山雷頤 艮上震下","description":"周易 - 第二十七卦 頤 山雷頤 艮上震下","frontmatter":{"title":"第二十七卦 頤 山雷頤 艮上震下","description":"周易 - 第二十七卦 頤 山雷頤 艮上震下"},"headers":[],"relativePath":"classics/zhouyi/028.md","filePath":"classics/zhouyi/028.md"}'),l={name:"classics/zhouyi/028.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="頤" tabindex="-1">頤 <a class="header-anchor" href="#頤" aria-label="Permalink to “頤”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>貞吉。觀頤，自求口實。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>頤貞吉，養正則吉也。觀頤，觀其所養也；自求口實，觀其自養也。天地養萬物，聖人養賢，以及萬民；頤之時義大矣哉！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山下有雷，頤；君子以慎言語，節飲食。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>舍爾靈龜，觀我朵頤，兇。象 曰：觀我朵頤，亦不足貴也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>顛頤，拂經，於丘頤，徵兇。象曰：六二徵兇，行失類也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>拂頤，貞兇，十年勿用，無攸利。象曰：十年勿用，道大悖也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>顛頤吉，虎視眈眈，其欲逐逐，無咎。象曰：顛頤之吉，上施光也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>拂經，居貞吉，不可涉大川。象曰：居貞之吉，順以從上也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>由頤，厲吉，利涉大川。象曰：由頤厲吉，大有慶也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
